from pathlib import Path

# Backend
Path('server/monthly-closings.ts').write_text(r'''import { getSql, readCookie, readJsonBody, sendJson, SESSION_COOKIE_NAME } from "../api/auth/_shared.js";

type User={id:number;role:string;name?:string|null;username?:string|null};
let schemaPromise:Promise<void>|null=null;
function ensureSchema(){if(schemaPromise)return schemaPromise;const sql=getSql();schemaPromise=(async()=>{await sql`CREATE TABLE IF NOT EXISTS monthly_closings (id bigserial PRIMARY KEY,"databaseId" integer NOT NULL REFERENCES databases(id) ON DELETE CASCADE,"month" varchar(7) NOT NULL,"snapshot" jsonb NOT NULL,"closedBy" integer REFERENCES users(id) ON DELETE SET NULL,"closedAt" timestamptz NOT NULL DEFAULT NOW(),UNIQUE("databaseId","month"))`;await sql`CREATE INDEX IF NOT EXISTS monthly_closings_database_month_idx ON monthly_closings ("databaseId","month" DESC)`;})().catch(e=>{schemaPromise=null;throw e});return schemaPromise;}
async function userFromSession(req:any):Promise<User|null>{const token=readCookie(req,SESSION_COOKIE_NAME);if(!token)return null;const sql=getSql();const rows=await sql`SELECT u.id,u.role,u.name,u.username FROM local_sessions s JOIN users u ON u.id=s."userId" WHERE s.token=${token} AND s."expiresAt">NOW() LIMIT 1`;return (rows[0] as any)||null;}
async function canAccessDatabase(user:User,databaseId:number){const sql=getSql();if(user.role==='super_admin'){const rows=await sql`SELECT id FROM databases WHERE id=${databaseId} LIMIT 1`;return Boolean(rows[0]);}const rows=await sql`SELECT 1 FROM user_database_access WHERE "userId"=${user.id} AND "databaseId"=${databaseId} LIMIT 1`;return Boolean(rows[0]);}
function validMonth(value:unknown){const m=String(value??'').trim();return /^\d{4}-(0[1-9]|1[0-2])$/.test(m)?m:null;}
function safeSnapshot(value:any){if(!value||typeof value!=='object'||Array.isArray(value))return null;const raw=JSON.stringify(value);if(raw.length>50000)return null;return value;}
export async function handleMonthlyClosings(req:any,res:any){try{await ensureSchema();const user=await userFromSession(req);if(!user)return sendJson(res,401,{success:false,message:'Sessão expirada.'});const sql=getSql();const databaseId=Math.trunc(Number(Array.isArray(req?.query?.databaseId)?req.query.databaseId[0]:req?.query?.databaseId||0));if(!databaseId)return sendJson(res,400,{success:false,message:'Selecione um banco de dados.'});if(!(await canAccessDatabase(user,databaseId)))return sendJson(res,403,{success:false,message:'Sem acesso a este banco de dados.'});
if(req.method==='GET'){const rows=await sql`SELECT mc.id,mc."databaseId",mc.month,mc.snapshot,mc."closedAt",mc."closedBy",COALESCE(NULLIF(u.name,''),NULLIF(u.username,''),'Usuário') AS "closedByName" FROM monthly_closings mc LEFT JOIN users u ON u.id=mc."closedBy" WHERE mc."databaseId"=${databaseId} ORDER BY mc.month DESC`;return sendJson(res,200,{success:true,closings:rows});}
if(req.method==='POST'){const body=await readJsonBody(req);const month=validMonth(body?.month);const snapshot=safeSnapshot(body?.snapshot);if(!month)return sendJson(res,400,{success:false,message:'Mês de fechamento inválido.'});const current=new Date().toISOString().slice(0,7);if(month>current)return sendJson(res,400,{success:false,message:'Não é possível fechar um mês futuro.'});if(!snapshot)return sendJson(res,400,{success:false,message:'Dados do fechamento inválidos.'});try{const rows=await sql`INSERT INTO monthly_closings ("databaseId",month,snapshot,"closedBy","closedAt") VALUES (${databaseId},${month},${JSON.stringify(snapshot)}::jsonb,${user.id},NOW()) RETURNING id,"databaseId",month,snapshot,"closedAt"`;return sendJson(res,201,{success:true,closing:rows[0],message:'Fechamento mensal registrado com sucesso.'});}catch(error:any){if(String(error?.code||'')==='23505')return sendJson(res,409,{success:false,message:'Este mês já foi fechado. Consulte-o em Fechamentos.'});throw error;}}
res.setHeader('Allow','GET, POST');return sendJson(res,405,{success:false,message:'Método não permitido.'});}catch(error){console.error('[monthly-closings]',error);return sendJson(res,500,{success:false,message:error instanceof Error?error.message:'Erro ao processar fechamento mensal.'});}}
''')

# Page
Path('client/src/pages/Fechamentos.tsx').write_text(r'''import DashboardLayout from "@/components/DashboardLayout";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { trpc } from "@/lib/trpc";
import { CalendarRange, ChevronDown, ChevronUp, RefreshCw, Wallet, CreditCard, Building2, Car, Package } from "lucide-react";
import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";
const money=(v:any)=>Number(v||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"});
const monthName=(m:string)=>{const [y,mo]=m.split('-').map(Number);return new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(new Date(y,mo-1,1));};
type Closing={id:number;databaseId:number;month:string;snapshot:any;closedAt:string;closedByName?:string|null};
function Mini({label,value}:{label:string;value:any}){return <div className="rounded-xl border bg-background p-3"><p className="text-xs text-muted-foreground">{label}</p><p className="mt-1 font-bold">{typeof value==='number'?money(value):value}</p></div>}
export default function Fechamentos(){const {data:activeDb}=trpc.databases.getActive.useQuery();const [rows,setRows]=useState<Closing[]>([]);const [loading,setLoading]=useState(false);const [open,setOpen]=useState<number|null>(null);const load=useCallback(async()=>{if(!activeDb?.id){setRows([]);return;}setLoading(true);try{const r=await fetch(`/api/site-access?scope=monthly-closings&databaseId=${activeDb.id}`,{credentials:'include',cache:'no-store'});const j=await r.json().catch(()=>({}));if(!r.ok||!j?.success)throw new Error(j?.message||'Não foi possível carregar os fechamentos.');setRows(Array.isArray(j.closings)?j.closings:[]);}catch(e){toast.error(e instanceof Error?e.message:'Erro ao carregar fechamentos.');}finally{setLoading(false)}},[activeDb?.id]);useEffect(()=>{void load()},[load]);
return <DashboardLayout><div className="space-y-5"><div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><div className="flex items-center gap-2 text-sm font-semibold text-primary"><CalendarRange className="h-4 w-4"/>Histórico financeiro</div><h1 className="mt-1 text-3xl font-bold">Fechamentos mensais</h1><p className="mt-1 text-muted-foreground">Consulte mês a mês o retrato completo salvo no fechamento de <b>{activeDb?.name||'seu banco'}</b>.</p></div><Button variant="outline" onClick={()=>load()} disabled={loading}><RefreshCw className={`mr-2 h-4 w-4 ${loading?'animate-spin':''}`}/>Atualizar</Button></div>{loading?<Card><CardContent className="py-12 text-center text-muted-foreground">Carregando fechamentos...</CardContent></Card>:rows.length===0?<Card><CardContent className="py-12 text-center"><CalendarRange className="mx-auto mb-3 h-10 w-10 text-muted-foreground"/><p className="font-semibold">Nenhum mês fechado ainda.</p><p className="mt-1 text-sm text-muted-foreground">Faça o primeiro fechamento pelo Dashboard.</p></CardContent></Card>:<div className="space-y-3">{rows.map(c=>{const s=c.snapshot||{};const expanded=open===c.id;return <Card key={c.id}><CardHeader className="pb-3"><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><CardTitle className="capitalize">{monthName(c.month)}</CardTitle><p className="mt-1 text-xs text-muted-foreground">Fechado em {new Date(c.closedAt).toLocaleString('pt-BR')} {c.closedByName?`por ${c.closedByName}`:''}</p></div><div className="flex items-center gap-2"><span className={`rounded-full px-3 py-1 text-xs font-bold ${Number(s.cash?.monthlyBalance||0)>=0?'bg-emerald-500/10 text-emerald-700':'bg-red-500/10 text-red-700'}`}>Saldo do mês: {money(s.cash?.monthlyBalance||0)}</span><Button size="sm" variant="outline" onClick={()=>setOpen(expanded?null:c.id)}>{expanded?<ChevronUp className="h-4 w-4"/>:<ChevronDown className="h-4 w-4"/>}</Button></div></div></CardHeader><CardContent><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Mini label="Entradas do mês" value={Number(s.cash?.monthlyInput||0)}/><Mini label="Saídas do mês" value={Number(s.cash?.monthlyOutput||0)}/><Mini label="Saldo geral no fechamento" value={Number(s.cash?.totalBalance||0)}/><Mini label="Total em aberto" value={Number(s.loans?.open||0)+Number(s.rentals?.pending||0)+Number(s.vehicles?.open||0)+Number(s.products?.open||0)}/></div>{expanded&&<div className="mt-5 grid gap-4 lg:grid-cols-2"><section className="rounded-xl border p-4"><h3 className="mb-3 flex items-center gap-2 font-bold"><CreditCard className="h-4 w-4 text-primary"/>Empréstimos</h3><div className="grid gap-2 sm:grid-cols-2"><Mini label="Emprestado" value={Number(s.loans?.lent||0)}/><Mini label="Recebido" value={Number(s.loans?.received||0)}/><Mini label="Em aberto" value={Number(s.loans?.open||0)}/><Mini label="Vencido" value={Number(s.loans?.overdue||0)}/></div></section><section className="rounded-xl border p-4"><h3 className="mb-3 flex items-center gap-2 font-bold"><Building2 className="h-4 w-4 text-primary"/>Aluguéis e imóveis</h3><div className="grid gap-2 sm:grid-cols-2"><Mini label="Aluguel previsto" value={Number(s.rentals?.expected||0)}/><Mini label="Aluguel recebido" value={Number(s.rentals?.paid||0)}/><Mini label="Vendas de imóveis" value={Number(s.properties?.totalSales||0)}/><Mini label="Recebido em imóveis" value={Number(s.properties?.received||0)}/></div></section><section className="rounded-xl border p-4"><h3 className="mb-3 flex items-center gap-2 font-bold"><Car className="h-4 w-4 text-primary"/>Veículos</h3><div className="grid gap-2 sm:grid-cols-2"><Mini label="Contratado" value={Number(s.vehicles?.total||0)}/><Mini label="Recebido" value={Number(s.vehicles?.paid||0)}/><Mini label="Em aberto" value={Number(s.vehicles?.open||0)}/><Mini label="Contratos" value={String(s.vehicles?.count||0)}/></div></section><section className="rounded-xl border p-4"><h3 className="mb-3 flex items-center gap-2 font-bold"><Package className="h-4 w-4 text-primary"/>Produtos e agentes</h3><div className="grid gap-2 sm:grid-cols-2"><Mini label="Produtos em aberto" value={Number(s.products?.open||0)}/><Mini label="Produtos recebidos" value={Number(s.products?.paid||0)}/><Mini label="Volume dos agentes" value={Number(s.agents?.volume||0)}/><Mini label="Maior performance" value={s.agents?.top||'—'}/></div></section></div>}</CardContent></Card>})}</div>}</div></DashboardLayout>}
''')

# site access route
p=Path('api/site-access.ts');s=p.read_text();
s=s.replace('import { handleReviews } from "../server/reviews.js";','import { handleReviews } from "../server/reviews.js";\nimport { handleMonthlyClosings } from "../server/monthly-closings.js";')
s=s.replace('  if(scope==="reviews")return handleReviews(req,res);','  if(scope==="reviews")return handleReviews(req,res);\n  if(scope==="monthly-closings")return handleMonthlyClosings(req,res);')
p.write_text(s)

# App route
p=Path('client/src/App.tsx');s=p.read_text();
s=s.replace('const Tutorial = lazy(() => import("./pages/Tutorial"));','const Tutorial = lazy(() => import("./pages/Tutorial"));\nconst Fechamentos = lazy(() => import("./pages/Fechamentos"));')
s=s.replace('const PaidTutorial = () => <CommercialPaymentGate><Tutorial /></CommercialPaymentGate>;','const PaidTutorial = () => <CommercialPaymentGate><Tutorial /></CommercialPaymentGate>;\nconst PaidFechamentos = () => <CommercialPaymentGate><Fechamentos /></CommercialPaymentGate>;')
s=s.replace('      <Route path={"/tutorial"} component={PaidTutorial} />','      <Route path={"/tutorial"} component={PaidTutorial} />\n      <Route path={"/fechamentos"} component={PaidFechamentos} />')
p.write_text(s)

# DashboardLayout menu
p=Path('client/src/components/DashboardLayout.tsx');s=p.read_text();
s=s.replace('Activity, Building2, CalendarDays, Car, ChevronRight, ClipboardList, CreditCard, Database,','Activity, Building2, CalendarDays, CalendarRange, Car, ChevronRight, ClipboardList, CreditCard, Database,')
s=s.replace('    { name: "Caixa", href: "/caixa", icon: Wallet, show: Boolean(user?.canView && regularAccess) },','    { name: "Caixa", href: "/caixa", icon: Wallet, show: Boolean(user?.canView && regularAccess) },\n    { name: "Fechamentos", href: "/fechamentos", icon: CalendarRange, show: Boolean(user?.canView && regularAccess) },')
p.write_text(s)

# Dashboard closing card
p=Path('client/src/pages/Dashboard.tsx');s=p.read_text();
s=s.replace('import { Activity, BadgeDollarSign, Building2, Car, CreditCard, Eye, EyeOff, Focus, Package, Settings2, Users, Wallet, X } from "lucide-react";','import { Activity, BadgeDollarSign, Building2, CalendarRange, Car, CheckCircle2, CreditCard, Eye, EyeOff, Focus, Loader2, Package, Settings2, Users, Wallet, X } from "lucide-react";\nimport { toast } from "sonner";\nimport { Link } from "wouter";')
s=s.replace('  const [focused,setFocused]=useState<BlockKey|null>(null);','  const [focused,setFocused]=useState<BlockKey|null>(null);\n  const [closingBusy,setClosingBusy]=useState(false);\n  const [closedMonths,setClosedMonths]=useState<string[]>([]);')
needle='  const agentRanking=(performance?.ranking??[]).map((a:any)=>({label:a.agentName||a.name||`Agente #${a.agentId}`,value:Number(a.paymentVolume||0)}));\n'
insert=needle+r'''  const currentMonth=monthKey(new Date());
  const currentMonthCash=useMemo(()=>{const rows=(cash as any[]).filter(x=>String(x.movementDate||"").slice(0,7)===currentMonth);const input=rows.filter(x=>x.type==="ENTRADA").reduce((sum,x)=>sum+Number(x.amount||0),0);const output=rows.filter(x=>x.type==="SAIDA").reduce((sum,x)=>sum+Number(x.amount||0),0);return {input,output,balance:input-output};},[cash,currentMonth]);
  useEffect(()=>{if(!activeDb?.id){setClosedMonths([]);return;}fetch(`/api/site-access?scope=monthly-closings&databaseId=${activeDb.id}`,{credentials:"include",cache:"no-store"}).then(r=>r.ok?r.json():null).then(j=>setClosedMonths(Array.isArray(j?.closings)?j.closings.map((x:any)=>String(x.month)):[])).catch(()=>{});},[activeDb?.id]);
  const closeMonth=async()=>{if(!activeDb?.id)return toast.error("Selecione um banco de dados.");if(closedMonths.includes(currentMonth))return toast.info("Este mês já foi fechado.");if(!window.confirm(`Confirmar o fechamento integral de ${currentMonth.split("-").reverse().join("/")}? O fechamento ficará salvo no histórico.`))return;setClosingBusy(true);try{const snapshot={cash:{monthlyInput:currentMonthCash.input,monthlyOutput:currentMonthCash.output,monthlyBalance:currentMonthCash.balance,totalInput:cashSummary.input,totalOutput:cashSummary.out,totalBalance:cashSummary.balance},loans:{active:Number(stats?.activeLoans?.count||0),lent:Number(stats?.loanMetrics?.totalLent||0),received:Number(stats?.loanMetrics?.totalReceived||0),open:Number(stats?.loanMetrics?.totalOpen||0),overdue:Number(stats?.loanMetrics?.totalOverdue||0)},rentals:{active:rentalSummary.active,expected:rentalSummary.expected,paid:rentalSummary.paid,pending:rentalSummary.pending},properties:{cashSales:propertySummary.cashSales,financed:propertySummary.financed,received:propertySummary.received,totalSales:propertySummary.totalSales},vehicles:{count:financeSplit.vehicle.count,total:financeSplit.vehicle.total,paid:financeSplit.vehicle.paid,open:financeSplit.vehicle.open},products:{count:financeSplit.product.count,total:financeSplit.product.total,paid:financeSplit.product.paid,open:financeSplit.product.open},agents:{count:agentRanking.length,volume:agentRanking.reduce((sum:number,a:any)=>sum+a.value,0),top:agentRanking[0]?.label||null},database:{id:activeDb.id,name:activeDb.name}};const response=await fetch(`/api/site-access?scope=monthly-closings&databaseId=${activeDb.id}`,{method:"POST",credentials:"include",headers:{"content-type":"application/json"},body:JSON.stringify({month:currentMonth,snapshot})});const result=await response.json().catch(()=>({}));if(!response.ok||!result?.success)throw new Error(result?.message||"Não foi possível fechar o mês.");setClosedMonths(v=>[currentMonth,...v]);toast.success("Fechamento mensal concluído e salvo no histórico.");}catch(e){toast.error(e instanceof Error?e.message:"Erro ao fechar o mês.");}finally{setClosingBusy(false)}};
'''
if needle not in s: raise SystemExit('agent needle missing')
s=s.replace(needle,insert)
marker='    {focused&&<div className="flex items-center justify-between rounded-xl border border-primary/20 bg-primary/5 p-3"><p className="text-sm font-medium">Modo de análise: {blocks.find(b=>b.key===focused)?.title}</p><Button size="sm" variant="ghost" onClick={()=>setFocused(null)}>Mostrar todos</Button></div>}\n'
card=marker+r'''    {!focused&&<Card className="border-primary/20 bg-gradient-to-br from-primary/[0.06] to-background"><CardContent className="p-5"><div className="flex flex-col gap-5 lg:flex-row lg:items-center lg:justify-between"><div className="flex items-start gap-3"><div className="rounded-xl bg-primary/10 p-3 text-primary"><CalendarRange className="h-6 w-6"/></div><div><p className="text-xs font-bold uppercase tracking-[.16em] text-primary">Fechamento mensal</p><h2 className="mt-1 text-xl font-bold">Fechamento integral de {currentMonth.split("-").reverse().join("/")}</h2><p className="mt-1 max-w-2xl text-sm text-muted-foreground">Salva um retrato completo do mês: entradas, saídas, saldo, empréstimos, aluguéis, imóveis, veículos, produtos e agentes. Depois você consulta tudo mês a mês na aba Fechamentos.</p></div></div><div className="min-w-[260px] rounded-xl border bg-background p-4"><div className="grid grid-cols-3 gap-2 text-center"><div><p className="text-[10px] uppercase text-muted-foreground">Entradas</p><p className="text-sm font-bold">{money(currentMonthCash.input)}</p></div><div><p className="text-[10px] uppercase text-muted-foreground">Saídas</p><p className="text-sm font-bold">{money(currentMonthCash.output)}</p></div><div><p className="text-[10px] uppercase text-muted-foreground">Saldo</p><p className="text-sm font-bold text-primary">{money(currentMonthCash.balance)}</p></div></div><div className="mt-4 flex gap-2">{closedMonths.includes(currentMonth)?<Button className="flex-1" variant="outline" disabled><CheckCircle2 className="mr-2 h-4 w-4"/>Mês fechado</Button>:<Button className="flex-1" onClick={closeMonth} disabled={closingBusy}>{closingBusy?<Loader2 className="mr-2 h-4 w-4 animate-spin"/>:<CalendarRange className="mr-2 h-4 w-4"/>}{closingBusy?"Fechando...":"Fechar mês"}</Button>}<Link href="/fechamentos"><a><Button variant="outline">Histórico</Button></a></Link></div></div></div></CardContent></Card>}
'''
if marker not in s: raise SystemExit('dashboard marker missing')
s=s.replace(marker,card)
p.write_text(s)
